// 궁합
function gung(){const [gy,gm,gd]=$('gBd').value.split('-').map(Number);if(!gy)return;const Q=saju(gy,gm,gd,-1,null);const ods=Q[2][0],odb=Q[2][1];const nm=esc($('gNm').value||'그 사람');const gmb=$('gMb').value;
 const rel=tg(ds,ods),rel2=tg(ods,ds);const cntO=[0,0,0,0,0];Q.forEach(([s,b])=>{cntO[SE[s]]++;cntO[BE[b]]++});
 const fill=cntO[r.lack]>=2?1:cntO[r.lack]===1?.5:0,fill2=r.cnt[cntO.indexOf(Math.min(...cntO))]>=2?1:0;const clash=CHG[P[2][1]]===odb,hap=HAP[P[2][1]]===odb;
 const glp=rd(String(gy).split('').concat(String(gm).split(''),String(gd).split('')).reduce((a,b)=>a+ +b,0));const same=ngOf(glp)===ngOf(r.lp);
 const mbm=[...S.mbti].filter((c,i)=>c===gmb[i]).length;
 const sc=[['일간 관계',[72,64,78,60,74][rel[1]]],['오행 보완',Math.round(45+(fill+fill2)*22)],['배우자궁',clash?35:hap?90:62],['운명수',same?82:60],['성격유형',[50,58,70,64,56][mbm]]];
 const tot=Math.round(sc.reduce((a,b)=>a+b[1],0)/sc.length);
 const goodY=[2026,2027,2028,2029,2030].filter(Y=>{const i=((Y-4)%60+60)%60;return HAP[P[2][1]]===i%12||HAP[odb]===i%12||GUI.includes(i%12)});
 $('gOut').innerHTML=`<div style="margin-top:16px;text-align:center"><span class="sc ${grade(tot)}" style="font-size:22px;padding:6px 14px">${tot}점</span></div>${sc.map(([a,v])=>`<div class="gbar"><span>${a}</span><i><b style="width:${v}%"></b></i><span>${v}</span></div>`).join('')}
 <p style="margin-top:14px"><b>💬 둘의 기본 관계</b> — ${nm}의 일간은 ${ST[ods]}(${EL(SE[ods])}), 니 기준으로 <b>${rel[0]}</b>이고, ${nm} 기준으로 너는 <b>${rel2[0]}</b>이야. 너한테 ${nm}은 「${GM[rel[0]]}」, ${nm}한테 너는 「${GM[rel2[0]]}」. 서로가 상대를 다르게 느낀다는 것부터 알고 시작해.</p>
 <p style="margin-top:10px"><b>🌊 서로 채우는 것</b> — ${fill>=1?`${nm}은 니 사주에 없는 ${jo(EL(r.lack),'을를')} 넉넉히 갖고 있어. 니 빈자리를 채워주는 사람이야.`:fill>0?`${nm}한테 ${jo(EL(r.lack),'이가')} 조금 있어서, 니 빈자리를 살짝 채워줘.`:`근데 ${nm}도 ${jo(EL(r.lack),'이가')} 없어. 둘 다 같은 데가 비어서, 같은 데서 같이 넘어질 수 있어.`}</p>
 <p style="margin-top:10px"><b>🏠 같이 살면</b> — ${clash?'배우자 자리끼리 충이 걸려. 처음엔 불꽃이 튀는데 오래 가면 서로 깎여. 생활 영역과 돈 관리를 처음부터 나눠.':hap?'배우자 자리끼리 합이 들어. 같이 있으면 편하고, 오래 갈 구조야. 다만 너무 편해서 서로 노력을 멈추지 않게.':'배우자 자리끼리는 큰 충돌도 큰 합도 없어. 둘이 어떻게 맞추느냐에 달렸어.'}</p>
 <p style="margin-top:10px"><b>🔢 숫자 리듬</b> — 니 운명수 ${r.lp}, ${nm} ${glp}. ${same?'같은 계열이라 템포가 맞아. 설명 안 해도 통하는 순간이 많아.':'다른 계열이라 템포가 달라. 한 명은 빠르고 한 명은 느린 순간이 자주 와. 그 차이를 서로의 역할로 나눠.'}</p>
 <p style="margin-top:10px"><b>🗣️ 대화 방식</b> — ${S.mbti}와 ${gmb}, 성격유형 ${mbm}자리가 같아. ${S.mbti[2]!==gmb[2]?'한 명은 이유를, 한 명은 마음을 먼저 봐. 싸울 때 니가 해결책부터 내밀면 상대는 무시당했다고 느껴.':'판단 방식이 같아서 대화는 잘 통하는데, 같은 데서 같이 고집을 부릴 수 있어.'}</p>
 <p style="margin-top:10px"><b>📅 둘에게 좋은 해</b> — ${goodY.length?goodY.join(', ')+'년':'뚜렷하지 않음'}. 이때 관계의 중요한 결정을 내려.</p>
 ${WHY(`상대 원국 ${Q.map(p=>ST[p[0]]+BR[p[1]]).join(' ')} (시간 미입력) · 일지 ${BR[P[2][1]]}↔${BR[odb]} · 상대 ${EL(r.lack)} ${cntO[r.lack]}개 · 운명수 계열 · 성격유형 일치 ${mbm}/4 · 총점 = 5항목 평균`)}`}
